  "failed_approaches": [
    {
      "id": "FAM:SF-CHT-025",
      "what_failed": "Assuming that play-type PPP differences represent real efficiency without accounting for labeling or foul artifacts.",
      "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"
    }
  ],
  "evidence_establishes": [
    "Sequential effects (defensive aftershocks) exist, where the outcome of a prior possession can influence the PPP of a subsequent possession (FAM:SF07). This supports the premise that an opponent's next-possession PPP could be affected by the preceding offensive play.",
